Translate("ptBR", "the-deadmines", {
	title = "Minas Mortas",
	sections = {
		{
			title = "Resumo",
			text = [=[As Minas Mortas ficam sob a aldeia de {link:moonbrook}Arroio da Lua{/link}, em {link:westfall}Cerro Oeste{/link}. Um dia foram as mais ricas minas de ouro das terras humanas. Hoje são o coração secreto da {link:defias-brotherhood}Irmandade Défias{/link}. Em suas profundezas, os pedreiros de {link:edwin-vancleef}Edwin VanCleef{/link} e os goblins que eles contrataram constroem algo que ninguém em {link:stormwind-city}Ventobravo{/link} viu ainda: um grande navio de guerra, escondido numa caverna marinha no fundo das minas.]=],
		},
		{
			title = "Origens",
			text = [=[Por gerações, as minas sob {link:moonbrook}Arroio da Lua{/link} mandaram ouro ao tesouro do {link:kingdom-of-stormwind}Reino de Ventobravo{/link}. Quando a {link:horde}Horda{/link} arrasou {link:stormwind-city}Ventobravo{/link} na {link:first-war}Primeira Guerra{/link}, os mineiros fugiram e as obras silenciaram. Os túneis foram deixados à escuridão, e o povo passou a chamá-los de Minas Mortas. Ficaram vazios durante os anos de exílio e reconstrução. Quando os pedreiros traídos vieram para o oeste, encontraram uma fortaleza já escavada à sua espera.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[A Irmandade fez da velha mina o seu santuário. Mineiros {link:defias-brotherhood}Défias{/link} cavam em seus poços, e magos e evocadores da Irmandade guardam seus salões. Artesãos e engenheiros goblins a soldo da Irmandade cortam madeira, fundem metal e montam máquinas. Um {link:ogres}ogro{/link} guarda o primeiro portão. Bem lá embaixo, onde os túneis se abrem para o mar, o navio está quase pronto, e seu capitão e sua tripulação aguardam a ordem de seu mestre. O que {link:edwin-vancleef}VanCleef{/link} pretende fazer com ele, só a Irmandade sabe. Muitos temem que se destine a {link:stormwind-city}Ventobravo{/link}.]=],
		},
		{
			title = "Dentro das Minas",
			text = [=[• {b}A Ala Desmoronada.{/b} Antes da entrada da Irmandade, uma passagem lateral leva a túneis onde um grupo de mineiros e exploradores anões foi soterrado quando o teto caiu. Eles não descansam. Seus mortos ainda andam pela escuridão com picaretas e dinamite.
• {b}A Sala dos Mastros.{/b} Aqui os goblins do mestre-madeireiro {link:sneed}Sneed{/link} cortam grandes troncos para o navio.
• {b}A Fundição.{/b} Aqui o goblin {link:gilnid}Gilnid{/link} funde o metal das minas.
• {b}{link:ironclad-cove}Covil Encouraçado{/link}.{/b} No fundo das minas há uma caverna aberta para o mar, onde o navio da Irmandade está ancorado. Seu portão está selado, e só pólvora e canhão o abrirão.
• {b}A Saída Oculta.{/b} Da enseada, uma passagem sobe até as colinas atrás de {link:moonbrook}Arroio da Lua{/link}, perto do mar.]=],
		},
		{
			title = "Os Que Habitam Embaixo",
			text = [=[Os servos da Irmandade aqui são muitos. O capataz {link:rhahkzor}Rhahk'Zor{/link}, os goblins {link:sneed}Sneed{/link} e {link:gilnid}Gilnid{/link} e a tripulação do navio sob o {link:captain-greenskin}Capitão Greenskin{/link} respondem todos a {link:edwin-vancleef}Edwin VanCleef{/link}. Perigos mais raros também espreitam nos túneis, entre eles um mineiro de grande força conhecido como Mineiro Johnson.]=],
		},
	},
})

Translate("ptBR", "ironclad-cove", {
	title = "Covil Encouraçado",
	sections = {
		{
			title = "Resumo",
			text = [=[O Covil Encouraçado é uma vasta caverna marinha no fundo das {link:the-deadmines}Minas Mortas{/link}, onde os túneis das antigas minas de ouro rompem até o Grande Oceano. Aqui a {link:defias-brotherhood}Irmandade Défias{/link} guarda seu maior segredo. Um navio de guerra está ancorado na água escura, construído com a madeira cortada na Sala dos Mastros e o metal fundido na Fundição. Piratas da Irmandade formam sua tripulação. Do convés superior, {link:edwin-vancleef}Edwin VanCleef{/link} comanda toda a sua Irmandade, e é aqui que ele decidiu resistir.]=],
		},
	},
})

Translate("ptBR", "edwin-vancleef", {
	title = "Edwin VanCleef",
	subtitle = "Chefão da Irmandade Défias",
