			text = [=[Por muito tempo a Irmandade não teve rosto. Então {link:master-mathias-shaw}Mathias Shaw{/link}, do {link:si-7}SI:7{/link}, deu-lhe um. A antiga guilda de pedreiros, escreveu ele, era liderada por um homem chamado Edwin VanCleef, um homem que havia reconstruído {link:stormwind-city}Ventobravo{/link} e não recebera agradecimento por isso.]=],
		},
		{
			title = "A Carta do Mensageiro",
			hint = [=[Intercepte o mensageiro da Irmandade nas estradas de Cerro Oeste.]=],
			text = [=[Um mensageiro {link:defias-brotherhood}Défias{/link} cavalgava pelas estradas entre {link:moonbrook}Arroio da Lua{/link}, a pedreira e a {link:jangolode-mine}Mina Veiojango{/link}. A mensagem que levava era prova firme de que a Irmandade respondia a VanCleef. Não dizia onde ele se escondia.]=],
		},
		{
			title = "O Esconderijo",
			hint = "Siga o traidor Défias até o covil da Irmandade.",
			text = [=[Um ladrão capturado comprou a própria vida guiando a milícia até {link:moonbrook}Arroio da Lua{/link}. Sob a aldeia, na velha mina de ouro, VanCleef e seus pedreiros esperavam.]=],
		},
		{
			title = "A Queda do Chefão",
			hint = "Desça ao fundo das Minas Mortas.",
			text = [=[No fundo das minas, no convés de seu navio, VanCleef enfrentou os que tinham vindo buscá-lo. Não se rendeu. Chamou seus guardas para o seu lado e lutou, como {link:baros-alexston}Baros Alexston{/link} se lembrava dele lutando em seus anos de juventude, sem igual. Quando caiu, sua cabeça foi levada de volta ao {link:sentinel-hill}Morro da Sentinela{/link}.]=],
		},
		{
			title = "A Carta Não Enviada",
			hint = "Reviste os pertences de VanCleef e entregue o que encontrar.",
			text = [=[Entre os pertences de VanCleef havia uma carta lacrada, nunca enviada, endereçada a {link:baros-alexston}Baros Alexston{/link}, o Arquiteto da {link:stormwind-city}Cidade de Ventobravo{/link}. Baros o conhecera na guilda. Ao lê-la, chamou VanCleef de idealista e ainda romântico, um homem consumido pela vingança. Também confessou que não conseguia culpá-lo por inteiro.]=],
		},
