		},
		{ text = "Red Silk Bandanas" },
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "caça-o" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "outrora pedreiro de sua guilda" },
		{ id = "bazil-thredd", name = "Bazil Thredd", note = "seu tenente" },
		{ id = "master-mathias-shaw", name = "Mestre Mathias Shaw", note = "revelou seu nome" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "morreu na revolta que ele liderou" },
